\label{linfest}

For $\tau>0$ and $q\in M_\infty$,
\[
 |\nabla l_\infty(q,\tau)|\leq
 \frac3\tau d_{g_\infty(-\tau)}(q_\infty,q)
 +\sqrt{\frac3\tau}C_1(\tau).
\]
\end{corollary}
\begin{proof}
\sketch Pass to the limit in
Corollary~\ref{cor:l-function-distance-bound}, using weak lower
semicontinuity.
\end{proof}

